const $=id=>document.getElementById(id),node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
const kinds=['human','ai_uninsured','ai_assured'],categories={human:['human','uninsured','other','transition'],ai_uninsured:['fde','ai','supervision','uninsured','other','transition'],ai_assured:['fde','ai','assurance','supervision','uninsured','other','transition']},labels={human:'现状人工',ai_uninsured:'AI无保障',ai_assured:'AI加拟议保障',fde:'FDE费用',ai:'AI部署运行',assurance:'保障费用',supervision:'监督维护',uninsured:'未获赔损失',other:'其他成本',transition:'一次性转型',onboarding:'接入技术收入',service:'持续服务收入',technical:'其他技术收入',premium:'承保方保费',acquisition:'获客成本',delivery:'交付成本',support:'支持成本',operations:'运营成本'};
let draft=null,loaded=null,epoch=0,busy=false;const keys=new Map();
const newLine=category=>({id:category,category,payer:'企业',amount:null,basis:'estimated',sourceRefs:[],sourceNote:'',includedIn:null,amortizationPeriods:1,allocationPeriod:1,fixed:false,contractConfirmed:false});
const newGroup=()=>({currency:'USD',scale:2,scenarios:kinds.map(kind=>({kind,qualityDefinition:'',qualifiedOutputs:null,lines:categories[kind].map(newLine)})),platform:{customers:null,revenues:['onboarding','service','technical','premium'].map(category=>({...newLine(category),payer:'客户'})),costs:['acquisition','delivery','support','operations'].map(category=>({...newLine(category),payer:'平台'}))}});
function clear(){epoch++;draft=null;loaded=null;$('editor').replaceChildren();$('results').replaceChildren();$('history').textContent='';}
async function request(path,options={}){const token=sessionStorage.getItem('incident-session');if(!token)throw Error('请先登录');const response=await fetch('/api/incidents-v1'+path,{...options,headers:{authorization:'Bearer '+token,...(options.body?{'content-type':'application/json'}:{}),...(options.key?{'idempotency-key':options.key}:{})}});if(!response.ok){if(response.status===401){sessionStorage.removeItem('incident-session');clear();}throw Error((await response.json()).error);}return response.json();}
async function guard(fn){if(busy)return;busy=true;try{await fn();}catch(e){$('status').textContent=e.message;}finally{busy=false;}}
function input(value,change,type='text'){const e=node('input');e.type=type;if(type==='checkbox')e.checked=value;else e.value=value??'';e.oninput=()=>change(type==='checkbox'?e.checked:e.value);return e;}
function field(parent,label,value,change,type='text'){const l=node('label',label+' '),i=input(value,change,type);l.append(i);parent.append(l);return i;}
function select(value,items,change){const e=node('select');for(const [v,label] of items){const option=node('option',label);option.value=v;e.append(option);}e.value=value;e.onchange=()=>change(e.value);return e;}
const nullable=v=>v.trim()===''?null:v.trim();
function lines(parent,rows,mode){const wrapper=node('div');wrapper.style.overflowX='auto';const table=node('table'),head=node('tr');for(const label of ['项目','付款方','金额（空=未知）','依据','来源说明','原件引用（每行一项）','分摊月数/本期序','已含FDE/固定成本/合同'])head.append(node('th',label));table.append(head);
 for(const row of rows){const tr=node('tr');tr.append(node('td',labels[row.category]??row.category));const cell=e=>{const td=node('td');td.append(e);tr.append(td);};cell(input(row.payer,v=>row.payer=v));cell(input(row.amount,v=>row.amount=nullable(v)));cell(select(row.basis,[['estimated','估计'],['actual','实际声明']],v=>row.basis=v));cell(input(row.sourceNote,v=>row.sourceNote=v));const refs=node('textarea');refs.value=row.sourceRefs.join('\n');refs.placeholder='importId/objectId';refs.oninput=()=>row.sourceRefs=refs.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);cell(refs);
 const allocation=node('div');if(['transition','acquisition'].includes(row.category)){field(allocation,'月数',row.amortizationPeriods,v=>row.amortizationPeriods=Number(v),'number');field(allocation,'本期序',row.allocationPeriod,v=>row.allocationPeriod=Number(v),'number');}else allocation.textContent='本月';cell(allocation);
 const flags=node('div');if(mode==='enterprise'&&rows.some(r=>r.category==='fde')&&!['fde','transition'].includes(row.category))field(flags,'已含FDE',row.includedIn!==null,v=>row.includedIn=v?rows.find(r=>r.category==='fde').id:null,'checkbox');if(mode==='cost')field(flags,'固定成本',row.fixed,v=>row.fixed=v,'checkbox');if(mode==='revenue'&&row.category!=='premium')field(flags,'合同已确认',row.contractConfirmed,v=>row.contractConfirmed=v,'checkbox');cell(flags);table.append(tr);
 }wrapper.append(table);parent.append(wrapper);}
function renderEditor(){const root=$('editor');root.replaceChildren();if(!draft)return;for(const group of draft.groups){const section=node('section');if(draft.groups.length>1){const remove=node('button','移除此币种分栏');remove.type='button';remove.onclick=()=>{draft.groups=draft.groups.filter(g=>g!==group);renderEditor();};section.append(remove);}field(section,'币种',group.currency,v=>group.currency=v);field(section,'小数位',group.scale,v=>group.scale=Number(v),'number');for(const scenario of group.scenarios){section.append(node('h3',labels[scenario.kind]));field(section,'质量定义',scenario.qualityDefinition,v=>scenario.qualityDefinition=v);field(section,'合格产出数量',scenario.qualifiedOutputs,v=>scenario.qualifiedOutputs=nullable(v));lines(section,scenario.lines,'enterprise');}section.append(node('h3','合作平台单位经济'));field(section,'本月客户数',group.platform.customers,v=>group.platform.customers=nullable(v));lines(section,group.platform.revenues,'revenue');lines(section,group.platform.costs,'cost');root.append(section);}}
function fraction(value){return value===null?'未知':value.denominator==='1'?value.numerator:`${value.numerator}/${value.denominator}`;}
function renderResults(record){$('results').replaceChildren();if(!record)return;if(record.calculation===null){$('results').append(node('p','本期间来源不可用，金额与ROI结果未知：'+record.sourceError+'。可更正凭据后保存新版本；历史快照不代表当前有效结果。'));return;}for(const group of record.calculation.groups){const section=node('section');section.append(node('h3',`${group.currency} / 小数位${group.scale}；金额均为最小单位`));for(const s of group.scenarios)section.append(node('p',`${labels[s.kind]}：${s.basis}，${s.comparable?'质量/数量声明可比':'不可比'}；期间成本 ${fraction(s.periodCost)}；现金成本 ${s.cashCost??'未知'}；每合格产出 ${fraction(s.unitCost)}；净节省 ${fraction(s.netSavings)}；ROI ${fraction(s.roi)}；缺项 ${s.missing.join(',')||'无'}；未知 ${s.unknown.join(',')||'无'}；重复凭据 ${s.duplicateRefs.length}；已含FDE ${s.excluded.join(',')||'无'}`));const p=group.platform;section.append(node('p',`平台：${p.basis}；合同已确认技术收入 ${fraction(p.eligibleTechnicalRevenue)}；未确认技术收入 ${fraction(p.proposedTechnicalRevenue)}；承保方保费 ${fraction(p.insurerPremium)}（不计平台收入）；期间成本 ${fraction(p.periodCost)}；现金成本 ${p.cashCost??'未知'}；贡献 ${fraction(p.contribution)}；经营结果 ${fraction(p.operatingResult)}；每客户贡献 ${fraction(p.contributionPerCustomer)}；盈亏平衡客户数 ${p.breakEvenCustomers??'未知/不可计算'}`),node('p',`缺失收入项 ${p.missingRevenue.join(',')||'无'}；未确认合同 ${p.unconfirmedContracts.join(',')||'无'}；缺失成本 ${p.missingCosts.join(',')||'无'}；未知成本 ${p.unknownCosts.join(',')||'无'}；重复凭据 ${p.duplicateRefs.length}`));$('results').append(section);}}
async function load(){const project=$('project').value,workflow=$('workflow').value,period=$('period').value;clear();const current=epoch,result=await request(`/workflows/${encodeURIComponent(workflow)}/roi?projectId=${encodeURIComponent(project)}`);if(current!==epoch)return;const record=result.periods.find(r=>r.period===period);loaded={project,workflow,period,version:record?.version??0};draft=record?structuredClone(record.input):{groups:[newGroup()]};renderEditor();renderResults(record);$('history').textContent=JSON.stringify(result.history.map(r=>({period:r.period,version:r.version,actorId:r.actorId,createdAt:r.createdAt,input:r.input})),null,2);sessionStorage.setItem('roi-last',JSON.stringify({project,workflow,period}));$('status').textContent=`当前期间版本 ${loaded.version}；数据声明未独立核验`;}
$('load').onsubmit=e=>{e.preventDefault();guard(load);};$('add-currency').onclick=()=>{if(!draft){$('status').textContent='先读取期间';return;}if(draft.groups.length>=8)return;draft.groups.push(newGroup());renderEditor();};
$('save').onsubmit=e=>{e.preventDefault();guard(async()=>{if(!loaded||!draft)throw Error('先读取期间');const selected=loaded,current=epoch,body=JSON.stringify({projectId:selected.project,expectedVersion:selected.version,input:draft}),identity=sessionStorage.getItem('incident-session')+selected.workflow+selected.period+body,key=keys.get(identity)??crypto.randomUUID();keys.set(identity,key);await request(`/workflows/${encodeURIComponent(selected.workflow)}/roi-periods/${encodeURIComponent(selected.period)}`,{method:'PUT',body,key});if(current===epoch)await load();});};
for(const id of ['project','workflow','period'])$(id).oninput=()=>{clear();sessionStorage.removeItem('roi-last');};$('logout').onclick=()=>guard(async()=>{try{await request('/session',{method:'DELETE'});}finally{sessionStorage.removeItem('incident-session');sessionStorage.removeItem('roi-last');keys.clear();clear();$('status').textContent='已退出';}});
$('project').value=sessionStorage.getItem('incident-project')||'';try{const saved=JSON.parse(sessionStorage.getItem('roi-last')||'null');if(saved&&sessionStorage.getItem('incident-session')){for(const id of ['project','workflow','period'])$(id).value=saved[id];guard(load);}}catch{sessionStorage.removeItem('roi-last');}


